nav.example:
# 使用`regex`式搜索关键字
apropos {{正则表达式}}
# 搜索时不限制输出到终端宽度
apropos {{[-l|--long]}} {{正则表达式}}
# 搜索与给定的所有表达式都匹配的页面
apropos {{正则表达式_1}} {{[-a|--and]}} {{正则表达式_2}} {{[-a|--and]}} {{正则表达式_3}}

# 读取键盘输入的数据赋值给变量
read {{变量}}
# 将您输入的每一行存储为数组一个元素
read -a {{数组}}
# 指定要读取的字符数，将数据赋值给变量
read -n {{字符数}} {{变量}}
# 将多个数据依次赋值给多个变量
read {{_ 变量1 _ 变量2}} <<<"{{The surname is Bond}}"

# 打印指定命令的 tldr 页面（提示：这就是你来到这里的方式！）
tldr {{命令}}
# 打印指定子命令的 tldr 页面
tldr {{命令}} {{子命令}}
# 用指定语言打印命令的 tldr 页面（如果没有，返回英语）
tldr {{[-L|--language]}} {{语言代码}} {{命令}}
# 打印指定平台的命令的 tldr 页面
tldr {{[-p|--platform]}} {{android|common|freebsd|linux|osx|netbsd|openbsd|sunos|windows}} {{命令}}

# 列出命令和预期事件的名称
trap
# 在接收到信号时执行命令
trap 'echo "捕获到信号 {{SIGHUP}}"' {{HUP}}
# 移除命令
trap - {{HUP}} {{INT}}

# 跳转到包含指定通配符的目录
j {{通配符表达式}}
# 跳转到包含指定通配符的目录的下一级
jc {{通配符表达式}}
# 使用系统文件管理器，打开指定的目录
jo {{通配符表达式}}
# 从 autojump 数据库中删除不存在的目录
j --purge

# 从字面上执行 `ls` 程序，即使存在 `ls` 别名
command {{ls}}
# 显示指定命令的可执行程序路径或别名定义
command -v {{命令名}}

# 跳转到一个名字带有 "foo" 的文件夹
z {{foo}}
# 跳转到一个名字带有 "foo" 并且后面带有 "bar" 的文件夹（例：`fooesbar`）
z {{foo}} {{bar}}
# 跳转到名字带有 "foo" 并且拥有最高访问次数的文件夹
z -r {{foo}}
# 跳转到最近使用的名字带有 "foo" 的文件夹
z -t {{foo}}

# 转到名称中包含 "foo" 的排名最高的目录
zoxide query {{foo}}
# 转到名称中依次包含 "foo" 和 "bar" 的排名最高的目录
zoxide query {{foo}} {{bar}}
# 启动一个交互式目录搜索（需要 `fzf`）
zoxide query --interactive
# 添加一个目录或提升其排名
zoxide add {{路径/到/目录}}

file.example:
# 可访问书签清单
l
# 保存当前目录到某书签里
s {{书签名}}
# 跳转到指定书签
g {{书签名}}
# 打印书签目录内容
p {{书签名}}

# 以给定单位（KiB/MiB/GiB）列出目录和所有子目录的大小
du -{{k|m|g}} {{目标文件夹}}
# 以可读形式列出目录和任何子目录的大小（即自动为转换为选择的适当单位 kb|mb|gb）
du -h {{目标文件夹}}
# 以可读单位显示目录大小
du -sh {{目标文件夹}}
# 列出目录以及其中所有文件和目录的可读大小
du -ah {{目标文件夹}}

# 每行列出一个文件
exa {{[-1|--oneline]}}
# 列出所有文件，包括隐藏文件
exa {{[-a|--all]}}
# 以长格式列出所有文件（包含权限、所有者、大小和修改日期）
exa {{[-l|--long]}} {{[-a|--all]}}
# 列出文件，最大的排在最上面
exa {{[-r|--reverse]}} {{[-s|--sort]}} {{size}}

# 每行列出一个文件
eza {{[-1|--oneline]}}
# 列出所有文件，包括隐藏文件
eza {{[-a|--all]}}
# 以长格式列出所有文件（包含权限、所有者、大小和修改日期）
eza {{[-al|--all --long]}}
# 列出文件，最大的排在最上面
eza {{[-r|--reverse]}} {{[-s|--sort]}} {{size}}

# 在当前目录中递归查找匹配特定模式的文件
fd "{{正则表达式}}"
# 在特定目录中查找文件
fd "{{正则表达式}}" {{路径/到/文件}}
# 查找具有特定扩展名的文件
fd {{[-e|--extension]}} {{扩展名}}
# 仅查找匹配特定模式的文件夹
fd "{{正则表达式}}" {{[-t|--type]}} {{[d|directory]}}

# 搜索单个目录
jdupes {{路径/到/目录}}
# 搜索多个目录
jdupes {{目录1 目录2 ...}}
# 递归地搜索所有目录
jdupes {{[-r|--recurse]}} {{路径/到/目录}}
# 递归地搜索目录，并让用户选择要保留的文件
jdupes {{[-d|--delete]}} {{[-r|--recurse]}} {{路径/到/目录}}

# 创建一个 15 千字节的空文件
mkfile -n 15k {{文件名}}
# 创建给定大小和单位的文件（bytes, KB, MB, GB）
mkfile -n {{大小}}{{b|k|m|g}} {{文件名}}
# 创建两个 4 兆字节的文件
mkfile -n 4m {{文件名 1}} {{文件名 2}}

# 以长格式（权限、所有权、大小和修改日期）列出 Zip 文件中的所有文件
zipinfo {{路径/到/压缩包.zip}}
# 列出 Zip 文件中的所有文件
zipinfo -1 {{路径/到/压缩包.zip}}

view.example:
# 寻找内容包含"小明"的文件，并列出所在的行数
ag {{小明}}
# 在指定目录中寻找内容包含 "foo" 的文件
ag {{小明}} {{指定的目录}}
# 寻找内容包含 "foo" 的文件，但只列出文件名
ag -l {{小明}}
# 忽略大小写，寻找内容包含 "ABC" 的文件，并只输出匹配的内容，而非整行
ag -i -o {{ABC}}

# 使用美化样式打印一个或多个文件的内容到 `stdout`
bat {{路径/到/文件1 路径/到/文件2 ...}}
# 将多个文件连接成一个目标文件
bat {{路径/到/文件1 路径/到/文件2 ...}} >{{路径/到/目标文件}}
# 移除修饰并禁用分页
bat {{[-pp|--style plain --pager never]}} {{路径/到/文件}}
# 使用不同的背景颜色高亮显示特定行或一行范围
bat {{[-H|--highlight-line]}} {{10|5:10|:10|10:|10:+5}} {{路径/到/文件}}

# 比较文件或目录
delta {{路径/到/旧文件或目录}} {{路径/到/新文件或目录}}
# 比较文件或目录，显示行号
delta {{[-n|--line-numbers]}} {{路径/到/旧文件或目录}} {{路径/到/新文件或目录}}
# 比较文件或目录，并排显示差异
delta {{[-s|--side-by-side]}} {{路径/到/旧文件或目录}} {{路径/到/新文件或目录}}
# 比较文件或目录，忽略任何 Git 配置设置
delta --no-gitconfig {{路径/到/旧文件或目录}} {{路径/到/新文件或目录}}

# 运行 glow 并选择文件查看
glow
# 渲染 Markdown 文件到终端
glow {{路径/到/文件}}
# 使用分页器查看 Markdown 文件
glow {{[-p|--pager]}} {{路径/到/文件}}
# 从 URL 查看文件
glow {{https://example.com/file.md}}

# 输出文件的前几行
head -n {{行数}} {{文件名}}
# 输出文件的前几个字节
head -c {{字节数}} {{文件名}}

# 根据第一个（默认）字段合并两个文件
join {{路径/到/文件1}} {{路径/到/文件2}}
# 使用逗号（而不是空格）作为字段分隔符合并两个文件
join -t ',' {{路径/到/文件1}} {{路径/到/文件2}}
# 将文件 1 的字段 3 与文件 2 的字段 1 合并
join -1 {{3}} -2 {{1}} {{路径/到/文件1}} {{路径/到/文件2}}
# 为文件 1 中的每行未配对的行生成一行
join -a {{1}} {{路径/到/文件1}} {{路径/到/文件2}}

# 它开始寻找一个给定的前缀
look {{前缀}} {{文件}}
# 查找行，忽略大小写
look {{[-f|--ignore-case]}} {{前缀}} {{文件}}

# 显示指定卷（'/'）的索引状态
mdutil -s {{/}}
# 打开 / 关闭给定卷的 Spotlight 索引
mdutil -i {{on|off}} {{指定卷文件夹}}
# 清除索引数据并重新建立索引
mdutil -E {{指定卷文件夹}}

# 漂亮地打印一个或多个规范格式的图形
nop {{路径/到/输入1.gv 路径/到/输入2.gv ...}} >{{路径/到/输出.gv}}
# 检查一个或多个图形的有效性，不生成输出图形
nop -p {{路径/到/输入1.gv 路径/到/输入2.gv ...}}
# 显示帮助
nop -?

# 将所有行合并为一行，使用 tab 作为分隔符
paste {{[-s|--serial]}} {{路径/到/文件}}
# 使用指定的分隔符将所有行合并为一行
paste {{[-s|--serial]}} {{[-d|--delimiters]}} {{分隔符}} {{路径/到/文件}}
# 并排合并两个文件，每个文件以 tab 分隔为单独的列
paste {{路径/到/文件1}} {{路径/到/文件2}}
# 并排合并两个文件，每个文件以指定的分隔符分隔为单独的列
paste {{[-d|--delimiters]}} {{分隔符}} {{路径/到/文件1}} {{路径/到/文件2}}

# 在 PDF 中查找与关键词匹配的行
pdfgrep {{关键词}} {{文件.pdf}}
# 包含每个匹配行的文件名和页码
pdfgrep {{[-H|--with-filename]}} {{[-n|--page-number]}} {{关键词}} {{文件.pdf}}
# 对以 "foo" 开头关键词搜索，返回前 3 个匹配项，不区分大小写
pdfgrep {{[-m|--max-count]}} 3 {{[-i|--ignore-case]}} '{{^foo}}' {{文件.pdf}}
# 在当前目录中扩展名为.pdf 的文件中递归查找关键词
pdfgrep {{[-r|--recursive]}} {{关键词}}

# 从 `.proto` 文件生成 Python 代码
protoc --python_out={{路径/到/输出目录}} {{输入文件.proto}}
# 从一个导入其他 `.proto` 文件的 `.proto` 文件生成 Java 代码
protoc --java_out={{路径/到/输出目录}} --proto_path={{路径/到/导入搜索路径}} {{输入文件.proto}}
# 生成多种语言的代码
protoc --csharp_out={{路径/到/c#_输出目录}} --js_out={{路径/到/js_输出目录}} {{输入文件.proto}}
# 从 `.proto` 文件将文本格式消息编码为协议消息
protoc <{{消息.txt}} --encode={{类型名称}} {{输入文件.proto}}

# 随机化文件中的行顺序并输出结果
shuf {{文件名}}
# 只输出结果的前 5 条
shuf --head-count=5 {{路径/到/文件}}
# 将结果输出写入另一个文件
shuf {{路径/到/输入文件}} --output {{路径/到/输出文件}}
# 生成范围（1-10）内的随机数
shuf --input-range=1-10

# 显示文件中最后 n 行
tail {{[-n|--lines]}} {{n}} {{路径/到/文件}}
# 从特定行号开始打印文件后续内容
tail {{[-n|--lines]}} +{{行号}} {{路径/到/文件}}
# 从给定文件末尾打印特定字节数量的内容
tail {{[-n|--lines]}} {{字节数}} {{路径/到/文件}}
# 打印给定文件的最后几行并保持读取直到 `<Ctrl c>`
tail {{[-f|--follow]}} {{路径/到/文件}}

# 创建一个包含 C 语言解析器代码的文件 `y.tab.c`，并编译语法文件以及所有值所需的常量声明。（只有在使用 `-d` 选项时，才会创建常量声明文件 `y.tab.h`）
yacc -d {{路径/到/grammar_file.y}}
# 编译一个包含解析器描述的语法文件，以及报告由于语法中的歧义导致的冲突
yacc -d {{路径/到/grammar_file.y}} -v
# 编译一个语法文件，并用 `prefix` 代替 `y` 作为输出文件名前缀
yacc -d {{路径/到/grammar_file.y}} -v -b {{前缀}}

# 通过 USB 或 NFC 启用某个应用程序（`--enable` 可以多次使用以指定更多应用程序）
ykman config {{usb|nfc}} {{[-e|--enable]}} {{otp|u2f|fido2|oath|piv|openpgp|hsmauth}}
# 通过 USB 或 NFC 禁用某个应用程序（`--disable` 可以多次使用以指定更多应用程序）
ykman config {{usb|nfc}} {{[-d|--disable]}} {{otp|u2f|fido2|oath|piv|openpgp|hsmauth}}
# 禁用 NFC 上的所有应用程序
ykman config nfc {{[-D|--disable-all]}}

# 以漂亮打印格式输出 YAML 文件（v4+）
yq eval {{路径/到/file.yaml}}
# 以漂亮打印格式输出 YAML 文件（v3）
yq read {{路径/到/file.yaml}} {{[-C|--colors]}}
# 输出仅包含数组的 YAML 文件中的第一个元素（v4+）
yq eval '.[0]' {{路径/到/file.yaml}}
# 输出仅包含数组的 YAML 文件中的第一个元素（v3）
yq read {{路径/到/file.yaml}} '[0]'

# 创建一个新的触发器、创建、搜索或资源
zapier scaffold {{trigger|search|create|resource}} {{名称}}
# 为生成的文件指定一个自定义目标目录
zapier scaffold {{trigger|search|create|resource}} {{名称}} {{[-d|--dest]}}={{路径/到/目录}}
# 在生成文件时覆盖已有文件
zapier scaffold {{trigger|search|create|resource}} {{名称}} {{[-f|--force]}}
# 从生成的文件中排除注释
zapier scaffold {{trigger|search|create|resource}} {{名称}} --no-help

# 编码一个文件
base32 {{路径/到/文件}}
# 按特定宽度包装编码输出（“0”表示禁用包装）
base32 {{[-w|--wrap]}} {{0|76|...}} {{路径/到/文件}}
# 解码一个文件
base32 {{[-d|--decode]}} {{路径/到/文件}}
# 从标准输入编码
{{某指令}} | base32

# 编码目标文件
base64 {{[-i|--input]}} {{目标文件}}
# 解码目标文件
base64 {{[-d|--decode]}} {{[-i|--input]}} {{base64 编码文件}}
# 通过标准输入管道进行解码
echo -n "{{目标字符串}}" | base64
# 解码标准输入管道内容
echo -n {{base64 字符串}} | base64 {{[-d|--decode]}}

# 以交互模式启动
qalc {{[-i|--interactive]}}
# 以简洁模式启动（仅输出结果）
qalc {{[-t|--terse]}}
# 更新货币兑换率
qalc {{[-e|--exrates]}}
# 非交互地执行计算
qalc {{66+99|2^4|6 feet to cm|1 bitcoin to USD|20 kmph to mph|...}}

perm.example:
# 授予所有者［u］执行［x］文件的权限
chmod u+x {{文件}}
# 授予所有者［u］读［r］和写［w］文件或目录的权限
chmod u+rw {{文件或目录}}
# 移除用户组［g］的文件执行［x］权限
chmod g-x {{文件}}
# 授予所有用户［a］读［r］以及执行［x］文件的权限
chmod a+rx {{文件}}

proc.example:
# 将本地安装的 `asciinema` 与 asciinema.org 账号关联
asciinema auth
# 新建录制并保存到本地文件（按 `<Ctrl d>` 或输入 `exit` 结束）
asciinema rec {{路径/到/录制文件.cast}}
# 从本地文件回放终端录制
asciinema play {{路径/到/录制文件.cast}}
# 回放托管在 <https://asciinema.org> 的终端录制
asciinema play https://asciinema.org/a/{{文件id}}

# 在终端中运行
glances
# 以网页服务器模式运行，在浏览器中查看结果
glances {{[-w|--webserver]}}
# 以服务器模式启动，允许其他 glances 客户端连接以查看数据
glances {{[-s|--server]}}
# 作为客户端连接到 glances 服务器
glances {{[-c|--client]}} {{主机名}}

# 运行 Python web 应用程序
gunicorn {{导入路径：应用程序}}
# 在 localhost 上监听 8080 端口
gunicorn {{[-b|--bind]}} localhost:8080 {{导入路径：应用程序}}
# 启用实时自动加载
gunicorn --reload {{导入路径：应用程序}}
# 使用 4 个工作进程处理请求
gunicorn {{[-w|--workers]}} 4 {{导入路径：应用程序}}

# 显示本机的主机名
hostname
# 显示主机名的网络地址
hostname {{[-i|--ip-address]}}
# 显示 FQDN（完全限定域名）
hostname {{[-f|--fqdn]}}
# 设置本机主机名
hostname {{新主机名}}

# 启动 `htop`
htop
# 启动 `htop`, 显示指定用户拥有的进程
htop {{[-u|--user]}} {{用户名}}
# 以树形视图显示进程的层级关系，展示父子进程之间的关系
htop {{[-t|--tree]}}
# 使用指定的 `sort_item` 对进程排序（使用 `htop --sort help` 获取可用选项）
htop {{[-s|--sort]}} {{sort_item}}

# 复制文件到目标目录
install {{路径/到/源文件1 路径/到/源文件2 ...}} {{路径/到/目标目录}}
# 复制文件到目标目录，并设置其所有权
install {{[-o|--owner]}} {{用户}} {{路径/到/源文件1 路径/到/源文件2 ...}} {{路径/到/目标目录}}
# 复制文件到目标目录，并设置其所属组
install {{[-g|--group]}} {{用户组}} {{路径/到/源文件1 路径/到/源文件2 ...}} {{路径/到/目标目录}}
# 复制文件到目标目录，并设置其权限
install {{[-m|--mode]}} {{+x}} {{路径/到/源文件1 路径/到/源文件2 ...}} {{路径/到/目标目录}}

# 打印 Java 进程的共享对象映射（类似 pmap 的输出）
jmap {{Java 进程号}}
# 打印堆摘要信息
jmap -heap {{文件名.jar}} {{Java 进程号}}
# 按类型打印堆使用的直方图
jmap -histo {{Java 进程号}}
# 将堆的内容转储到二进制文件中以使用 jhat 进行分析
jmap -dump:format=b,file={{路径/到/文件}} {{Java 进程号}}

# 从 JSON 或 JSON Lines 输入中打印表格
cat {{文件.json}} | jtbl
# 打印表格并指定用于换行的列宽
cat {{文件.json}} | jtbl --cols={{宽度}}
# 打印表格并截断行而不是换行
cat {{文件.json}} | jtbl {{[-t|--truncate]}}
# 打印表格并不换行或截断行
cat {{文件.json}} | jtbl {{[-n|--no-wrap]}}

# 指定存储目录（默认：Linux 和 macOS 为 `/data/db`，Windows 为 `C:\data\db`）
mongod --dbpath {{路径/到/目录}}
# 指定配置文件
mongod --config {{路径/到/文件}}
# 指定监听的端口（默认：27017）
mongod --port {{端口}}
# 指定数据库分析级别。0 为关闭，1 仅慢操作，2 所有（默认：0）
mongod --profile {{0|1|2}}

# 显示系统信息
neofetch
# 在输出中显示或隐藏指定的信息行，'信息名称'是配置文件中的函数名称，例如 memory
neofetch --{{enable|disable}} {{信息名称}}
# 隐藏或显示操作系统架构信息
neofetch --os_arch {{on|off}}
# 启用或禁用输出中的 CPU 品牌信息
neofetch --cpu_brand {{on|off}}

# 创建一个新项目
quarto create-project {{路径/到/目录}} --type {{book|default|website}}
# 创建一个新的博客网站
quarto create-project {{路径/到/目录}} --type {{website}} --template {{blog}}
# 将输入文件渲染为不同格式
quarto render {{路径/到/文件.ext}} --to {{html|pdf|docx}}
# 渲染并预览文档或网站
quarto preview {{路径/到/目录 | 路径/到/文件}}

# 启动交互式菜单来配置 rclone
rclone config
# 列出 rclone 远程目录的内容
rclone lsf {{远程名}}:{{路径/到/目录}}
# 将文件或目录从本地计算机复制到远程目标
rclone copy {{路径/到/本地文件或目录}} {{远程名}}:{{路径/到/目录}}
# 将过去 24 小时内修改过的文件从本地复制到远程，并向用户逐个文件确认
rclone copy {{[-i|--interactive]}} --max-age 24h {{远程名}}:{{路径/到/目录}} {{路径/到/本地目录}}

# 以当前用户身份启动 runit 服务
runsv {{路径/到/服务目录}}
# 以 root 用户身份启动 runit 服务
sudo runsv {{路径/到/服务目录}}

# 以当前用户身份启动和管理目录中的所有服务
runsvdir {{路径/到/服务目录}}
# 以 root 用户身份启动和管理目录中的所有服务
sudo runsvdir {{路径/到/服务目录}}
# 在单独会话中启动服务
runsvdir -P {{路径/到/服务目录}}

# 按秒数延迟
sleep {{seconds}}
# 在 20 秒延迟后执行指定命令
sleep 20 && {{command}}

# 使用指定路径启动 `spf`
spf {{path/to/directory}}
# 使用多个路径启动 `spf`
spf {{path/to/directory1 path/to/directory2 ...}}
# 修复快捷键设置，补全缺失的按键
spf {{[--fh|--fix-hotkeys]}}
# 修复配置文件，补全缺失的项
spf {{[--fch|--fix-config-file]}}

# 启动服务
sudo sv up {{路径/到/服务目录}}
# 停止服务
sudo sv down {{路径/到/服务目录}}
# 获取服务状态
sudo sv status {{路径/到/服务目录}}
# 重载服务
sudo sv reload {{路径/到/服务目录}}

# 启动一个新会话
tmux
# 启动一个指定名称的新会话（[s]ession）
tmux {{[new|new-session]}} -s {{name}}
# 列出现有会话
tmux {{[ls|list-sessions]}}
# 连接到最近使用的会话
tmux {{[a|attach]}}

# 运行 Python Web 应用
uvicorn {{导入路径:应用对象}}
# 在本地主机上监听端口 8080
uvicorn --host localhost --port 8080 {{导入路径:应用对象}}
# 启用实时重新加载
uvicorn --reload {{导入路径:应用对象}}
# 使用 4 个工作进程处理请求
uvicorn --workers 4 {{导入路径:应用对象}}

# 使用默认配置文件启动代理
zabbix_agent2
# 使用自定义配置文件启动代理
zabbix_agent2 {{[-c|--config]}} {{路径/到/zabbix_agent2.conf}}
# 测试配置文件并退出
zabbix_agent2 {{[-c|--config]}} {{路径/到/zabbix_agent2.conf}} {{[-T|--test-config]}}
# 测试指定监控项并输出详细信息
zabbix_agent2 {{[-c|--config]}} {{路径/到/zabbix_agent2.conf}} {{[-t|--test]}} {{监控项键值}} {{[-v|--verbose]}}

# 使用默认配置文件启动 agent
zabbix_agentd
# 使用自定义配置文件启动 agent
zabbix_agentd {{[-c|--config]}} {{路径/到/zabbix_agentd.conf}}
# 在前台运行 agent（保持附着在当前终端会话中）
zabbix_agentd {{[-c|--config]}} {{路径/到/zabbix_agentd.conf}} {{[-f|--foreground]}}
# 测试配置文件
zabbix_agentd {{[-c|--config]}} {{路径/到/zabbix_agentd.conf}} {{[-T|--test-config]}}

# 使用默认配置文件启动服务器
zabbix_server
# 使用自定义配置文件启动服务器
zabbix_server {{[-c|--config]}} {{路径/到/zabbix_server.conf}}
# 在前台运行服务器
zabbix_server {{[-c|--config]}} {{路径/到/zabbix_server.conf}} {{[-f|--foreground]}}
# 测试配置文件并退出
zabbix_server {{[-c|--config]}} {{路径/到/zabbix_server.conf}} {{[-T|--test-config]}}

# 启动一个新的命名会话
zellij {{[-s|--session]}} {{名称}}
# 列出现有会话
zellij {{[ls|list-sessions]}}
# 附加到最近使用的会话
zellij {{[a|attach]}}
# 打开一个新窗格（在 zellij 会话中）
<Alt n>

# 以新的根目录，运行命令
sudo chroot {{路径/到/新/根目录}} {{命令}}
# 使用指定的用户和组
sudo chroot --userspec {{用户名或用户id:组名或组id}}

net.example:
# 向目标 URL 执行 100 次 HTTP GET 请求
ab -n 100 {{url}}
# 使用 10 个并发请求，同时向目标 URL 执行 100 次 HTTP GET 请求
ab -n 100 -c 10 {{url}}
# 使用来自文件的 JSON 负载对 URL 执行 100 个 HTTP POST 请求
ab -n 100 -T {{application/json}} -p {{path/to/file.json}} {{url}}
# 使用 HTTP [K]eep Alive，即在一个 HTTP 会话中执行多个请求
ab -k {{url}}

# 运行并生成一个私钥和证书
agate --content {{路径/到/内容}}/ --addr {{[::]:1965}} --addr {{0.0.0.0:1965}} --hostname {{example.com}} --lang {{en-US}}
# 启动服务器
agate {{路径/到/目录}}
# 显示帮助
agate {{[-h|--help]}}

# 打开特定文件或目录
agy {{路径/到/文件或目录}}
# 比较两个文件
agy {{[-d|--diff]}} {{路径/到/文件1}} {{路径/到/文件2}}
# 传入提示词来运行一个在当前工作目录的聊天会话
agy chat "{{提示词}}"
# 安装或卸载特定扩展
agy --{{install|uninstall}}-extension {{发布者.扩展|路径/到/扩展.vsix}}

# 使用字典文件破解捕获文件中的密钥
aircrack-ng -w {{路径/到/字典文件.txt}} {{路径/到/捕获文件.cap}}
# 使用多线程和字典文件破解捕获文件中的密钥
aircrack-ng -p {{线程数}} -w {{路径/到/字典文件.txt}} {{路径/到/捕获文件.cap}}
# 使用字典文件和接入点的 ESSID 破解捕获文件中的密钥
aircrack-ng -w {{路径/到/字典文件.txt}} -e {{extended_ssid}} {{路径/到/捕获文件.cap}}
# 使用字典文件和接入点的 MAC 地址破解捕获文件中的密钥
aircrack-ng -w {{路径/到/字典文件.txt}} --bssid {{mac}} {{路径/到/捕获文件.cap}}

# 从开放网络捕获文件中移除无线头，并使用接入点的 MAC 地址进行过滤
airdecap-ng -b {{ap_mac}} {{路径/到/捕获文件.cap}}
# 使用十六进制格式的密钥解密 WEP 加密的捕获文件
airdecap-ng -w {{hex_key}} {{路径/到/捕获文件.cap}}
# 使用接入点的 ESSID 和密码解密 WPA/WPA2 加密的捕获文件
airdecap-ng -e {{extended_ssid}} -p {{密码}} {{路径/到/捕获文件.cap}}
# 使用接入点的 ESSID 和密码解密 WPA/WPA2 加密的捕获文件，并保留头部信息
airdecap-ng -l -e {{extended_ssid}} -p {{密码}} {{路径/到/捕获文件.cap}}

# 共享文件或目录
airshare {{code}} {{路径/到/文件或目录1 路径/到/文件或目录2 ...}}
# 接收文件
airshare {{code}}
# 主机接收服务器（使用此选项可以通过 Web 接口上传文件）
airshare --upload {{code}}
# 将文件或目录发送到接收服务器
airshare --upload {{code}} {{路径/到/文件或目录1 路径/到/文件或目录2 ...}}

# 扫描当前本地网络
arp-scan {{[-l|--localnet]}}
# 扫描带有自定义位掩码的 IP 网络
arp-scan {{192.168.1.1}}/{{24}}
# 扫描自定义范围内的 IP 网络
arp-scan {{127.0.0.0}}-{{127.0.0.31}}
# 扫描带有自定义子网掩码的 IP 网络
arp-scan {{10.0.0.0}}:{{255.255.255.0}}

# 链接下载
axel {{超链接}}
# 链接下载，指定文件名
axel {{超链接}} {{[-o|--output]}} {{路径/到/文件}}
# 多连接数下载
axel {{[-n|--num-connections]}} {{连接数量}} {{超链接}}
# 查询镜像
axel {{[-S|--search=]}}{{镜像数量}} {{超链接}}

# 使用特定配置文件启动 Bird
bird -c {{路径/到/bird.conf}}
# 以特定用户和组身份启动 Bird
bird -u {{用户名}} -g {{组}}

# 启动 `btop`
btop
# 使用指定预设启动 `btop`
btop {{[-p|--preset]}} {{0..9}}
# 使用 16 种颜色和 TTY 友好的图形符号在 TTY 模式下启动 `btop`
btop {{[-t|--tty]}}
# 在 256 色模式而不是 24 位颜色模式下启动 `btop`
btop {{[-l|--low-color]}}

# 发起 HTTP GET 请求，将响应内容输出到 `stdout`
curl {{https://example.com}}
# 发起 HTTP GET 请求，自动跟随所有 `3xx` 重定向，将响应头和内容输出到 `stdout`
curl {{[-L|--location]}} {{[-D|--dump-header]}} - {{https://example.com}}
# 按照 URL 指定的文件名保存下载内容
curl {{[-O|--remote-name]}} {{https://example.com/filename.zip}}
# 以表单编码格式发送数据（`application/x-www-form-urlencoded` 类型的 POST 请求）。如需从 `stdin` 读取数据，可使用 `--data @file_name` 或 `--data @'-'`
curl {{[-X|--request]}} POST {{[-d|--data]}} '{{name=bob}}' {{http://example.com/form}}

# 使用默认配置文件（当前目录下的 `frpc.ini`）启动服务
frpc
# 使用新的 TOML 配置文件启动服务
frpc {{[-c|--config]}} {{路径/到/frpc.toml}}
# 使用指定的配置文件启动服务
frpc {{[-c|--config]}} {{路径/到/文件}}
# 检查配置文件的有效性
frpc verify {{[-c|--config]}} {{路径/到/文件}}

# 使用默认配置文件启动服务（假定当前目录中存在 `frps.ini`）
frps
# 使用新的 TOML 配置文件启动服务
frps {{[-c|--config]}} {{路径/到/frps.toml}}
# 使用指定的配置文件启动服务
frps {{[-c|--config]}} {{路径/到/文件}}
# 检查配置文件的有效性
frps verify {{[-c|--config]}} {{路径/到/文件}}

# 使用不同的详细（[v]erbosity）级别扫描远程主机的前 1000 个端口
nmap -v{{1|2|3}} {{ip或主机名}}
# 对整个子网或单个主机进行非常激进的 ping 扫描
nmap -T5 -sn {{192.168.0.0/24|ip或主机名1,ip或主机名2,...}}
# 对来自文件的主机启用操作系统检测、版本检测、脚本扫描和路由跟踪
sudo nmap -A -iL {{路径/到/文件.txt}}
# 扫描特定的端口列表（使用 `-p-` 扫描从 1 到 65535 的所有端口）
nmap -p {{端口1,端口2,...}} {{ip或主机名1,ip或主机名2,...}}

# 使用默认波特率 9600 连接到串行控制台
sudo picocom {{/dev/ttyXYZ}}
# 以指定波特率连接到串行控制台
sudo picocom {{/dev/ttyXYZ}} {{[-b|--baud]}} {{波特率}}
# 映射特殊字符（例如：将 `LF` 映射为 `CRLF`）
sudo picocom {{/dev/ttyXYZ}} --imap {{lfcrlf}}
# 退出 picocom
<Ctrl a><Ctrl x>

# 列出可用的服务名称
qdbus
# 列出指定服务的对象路径
qdbus {{服务名}}
# 列出指定对象可用的方法、信号和属性
qdbus {{服务名}} /{{路径/到/对象}}
# 执行指定方法，传递参数并显示返回值
qdbus {{服务名}} /{{路径/到/对象}} {{方法名}} {{参数1 参数2 ...}}

# 将您的密钥复制到远程主机
ssh-copy-id {{用户名}}@{{远程主机}}
# 将给定的公钥文件复制到远程主机
ssh-copy-id -i {{路径/到/公钥文件}} {{用户名}}@{{远程主机}}
# 将给定的公钥文件通过特定端口复制到远程主机
ssh-copy-id -i {{路径/到/公钥文件}} -p {{端口}} {{用户名}}@{{远程主机}}

# 通过远程 SSH 服务器转发所有 IPv4 TCP 流量
sshuttle {{[-r|--remote]}} {{用户名}}@{{服务器名}} {{0.0.0.0/0}}
# 同时将所有 DNS 流量转发到服务器的默认 DNS 解析器
sshuttle --dns {{[-r|--remote]}} {{用户名}}@{{服务器名}} {{0.0.0.0/0}}
# 转发所有流量，除了发往特定子网的流量
sshuttle {{[-r|--remote]}} {{用户名}}@{{服务器名}} {{0.0.0.0/0}} {{[-x|--exclude]}} {{192.168.0.1/24}}
# 使用 tproxy 方法转发所有 IPv4 和 IPv6 流量
sshuttle --method tproxy {{[-r|--remote]}} {{用户名}}@{{服务器名}} {{0.0.0.0/0}} {{::/0}} {{[-x|--exclude]}} {{你本地 IP 地址}} {{[-x|--exclude]}} {{SSH 服务器的 IP 地址}}

# 为当前目录启动 HTTP 服务器
updog
# 为指定目录启动 HTTP 服务器
updog --directory /{{路径/到/目录}}
# 在指定端口上启动 HTTP 服务器
updog --port {{端口}}
# 使用密码启动 HTTP 服务器（要登录，请将用户名留空，并在密码字段中输入密码）
updog --password {{密码}}

# 从网络摄像机拍照
wacaw {{文件名}}
# 录制视频
wacaw --video {{文件名}} {{[-D|--duration]}} {{录制多少秒}}
# 用自定义分辨率拍照
wacaw {{[-x|--width]}} {{宽}} {{[-y|--height]}} {{高}} {{文件名}}
# 将刚拍摄的图像复制到剪贴板
wacaw --to-clipboard

# 使用详细模式 Ping 主机的 80 端口（默认端口）
x tping {{host}}
# Ping 指定主机的特定端口
x tping {{host}}:{{port}}
# 以热力图形式显示结果
x tping {{[-m|--heatmap]}} {{host}}
# 以柱状图形式显示结果
x tping {{[-b|--bar]}} {{host}}:{{port}}

# 打印网络上指定媒体的媒体信息
you-get {{[-i|--info]}} {{https://example.com/video?id=value}}
# 从指定 URL 下载媒体
you-get {{https://example.com/video?id=value}}
# 在 Google 视频上搜索并下载
you-get {{关键词}}
# 将媒体下载到指定位置
you-get {{[-o|--output-dir]}} {{路径/到/目录}} {{[-O|--output-filename]}} {{文件名}} {{https://example.com/watch?v=value}}

# 通过歌曲名称下载（交互式选择）
ytmdl {{歌曲名称}}
# 不提示直接下载第一个结果
ytmdl {{[-q|--quiet]}} {{歌曲名称}}
# 将歌曲下载到指定目录
ytmdl {{[-o|--output-dir]}} {{路径/到/目录}} {{歌曲名称}}
# 从 YouTube URL 下载歌曲
ytmdl --url https://www.youtube.com/watch?v={{oHg5SJYRHA0}}

# 分析来自网络接口的实时流量
sudo zeek --iface {{接口}}
# 分析来自网络接口的实时流量并加载自定义脚本
sudo zeek --iface {{接口}} {{脚本1 脚本2 ...}}
# 分析来自网络接口的实时流量，不加载任何脚本
sudo zeek --bare-mode --iface {{接口}}
# 分析来自网络接口的实时流量，应用 `tcpdump` 过滤器
sudo zeek --filter {{路径/到/过滤器}} --iface {{接口}}

# 扫描一个子网或整个 IPv4 地址空间上的指定 TCP 端口（默认：80）
zmap {{SUBNETS}} {{[-p|--target-ports]}} {{端口}}
# 在一个子网中扫描指定的端口或端口范围
zmap {{[-p|--target-ports]}} {{端口1, 端口2-端口3,...}} {{SUBNETS}}
# 将结果输出到包含自定义字段的 CSV 文件中
zmap {{[-o|--output-file]}} {{路径/到/输出文件.csv}} {{[-f|--output-fields]}} "{{saddr, daddr, sport, dport}}" {{SUBNETS}}
# 将扫描速率限制为每秒指定数量的数据包
zmap {{[-r|--rate]}} {{每秒数据包数}} {{SUBNETS}}

# 运行 AdGuard Home
AdGuardHome
# 使用给定的配置文件运行 AdGuard Home
AdGuardHome --config {{给定的/配置文件.yaml}}
# 设置存储数据的工作目录
AdGuardHome --work-dir {{工作目录/路径}}
# 安装或卸载 AdGuard Home 的服务
AdGuardHome --service {{install|uninstall}}

# 使用指定存储目录打开 qutebrowser
qutebrowser --basedir {{路径/到/目录}}
# 使用临时设置打开 qutebrowser 实例
qutebrowser --set {{content.geolocation}} {{true|false}}
# 恢复一个 qutebrowser 实例的指定会话
qutebrowser --restore {{会话名称}}
# 启动 qutebrowser，使用指定方式打开所有 URL
qutebrowser --target {{auto|tab|tab-bg|tab-silent|tab-bg-silent|window|private-window}}

# 同步两个目录（第一次同步这两个目录时会创建日志）
unison {{路径/到/目录1}} {{路径/到/目录2}}
# 自动接受（无冲突的）默认值
unison {{路径/到/目录1}} {{路径/到/目录2}} -auto
# 使用模式忽略某些文件
unison {{路径/到/目录1}} {{路径/到/目录2}} -ignore {{模式}}
# 查看文档
unison -doc {{主题}}

# ping 指定的主机（省略则默认为 bing.com）
x ping {{host}}
# 以热力图形式显示 ping 结果
x ping {{[-m|--heatmap]}} {{host}}
# 以柱状图形式显示 ping 结果
x ping {{[-b|--bar]}} {{host}}
# 处理现有 ping 结果并以热力图显示
ping {{host}} | x ping vis {{[-m|--heatmap]}}

# 生成一个新的 ZeroTier 身份，并将私钥部分输出到 `stdout`
zerotier-idtool generate
# 生成一个新的 ZeroTier 身份，并将私钥和公钥部分保存到文件中
zerotier-idtool generate {{路径/到/identity.secret}} {{路径/到/identity.public}}
# 生成一个具有指定十六进制靓号前缀的 ZeroTier 身份（可能需要很长时间）
zerotier-idtool generate {{路径/到/identity.secret}} {{路径/到/identity.public}} {{靓号_前缀}}
# 从私钥身份中提取公钥部分
zerotier-idtool getpublic {{路径/到/identity.secret}}

dev.example:
# 与一个安卓设备配对（可在开发者选项中，找到地址和配对码）
adb pair {{ip_地址}}:{{端口}}
# 与一个安卓设备连接（端口与配对时存在差异）
adb connect {{ip_地址}}:{{端口}}
# 断开与设备的连接
adb disconnect {{ip_地址}}:{{端口}}

# 卸载一个软件包
adb uninstall {{com.example.app}}
# 卸载软件包，但是保留用户数据
adb uninstall -k {{com.example.app}}

# 将一个文件编译为一个对象文件
adscript --output {{路径/到/文件.o}} {{路径/到/输入文件.adscript}}
# 编译并链接一个文件到一个独立的可执行文件
adscript --executable --output {{路径/到/文件}} {{路径/到/输入文件.adscript}}
# 将文件编译成 LLVM IR 而不是本地机器码
adscript --llvm-ir --output {{路径/到/文件.ll}} {{路径/到/输入文件.adscript}}
# 将一个文件交叉编译为一个其他 CPU 架构或操作系统的目标文件
adscript --target-triple {{i386-linux-elf}} --output {{路径/到/文件.o}} {{路径/到/输入文件.adscript}}

# 生成用于 Azure 存储账户的 Terraform 配置
aiac get terraform {{用于 Azure 存储账户}}
# 生成一个 `nginx` 的 Dockerfile
aiac get dockerfile {{用于安全的 nginx}}
# 生成一个应用 Terraform 的 GitHub Actions 工作流
aiac get github action {{用于计划并应用 Terraform}}
# 生成一个用 Python 编写的端口扫描器
aiac get python {{扫描我网络中所有开放端口的代码}}

# 构建一个草稿
arduino --verify {{路径/到/文件.ino}}
# 构建草稿，并上传至设备
arduino --upload {{路径/到/文件.ino}}
# 构建草稿，并上传至带有一个 Atmega328p CPU 的 Arduino Nano（连接到端口 `/dev/ttyACM0`）
arduino --board {{arduino:avr:nano:cpu=atmega328p}} --port {{/dev/ttyACM0}} --upload {{路径/到/文件.ino}}
# 将首选项 `名称` 设定为特定 `值`
arduino --pref {{名称}}={{值}}

# 汇编文件，将输出写入 `a.out`
as {{路径/到/文件.s}}
# 将输出汇编到给定文件
as {{路径/到/文件.s}} -o {{路径/到/输出.o}}
# 通过跳过空白和注释预处理来更快地生成输出.（应该只用于受信任的编译器）
as -f {{路径/到/文件.s}}
# 在目录列表中包含一个给定路径，以搜索 `.include` 指令中指定的文件
as -I {{目标文件夹}} {{路径/到/文件.s}}

# 打开文件或目录
atom {{路径/到/文件或目录}}
# 在新窗口中打开文件或目录
atom {{[-n|--new-window]}} {{路径/到/文件或目录}}
# 在已有窗口中打开文件或目录
atom {{[-a|--add]}} {{路径/到/文件或目录}}
# 以安全模式启动 Atom（不加载额外插件）
atom --safe

# 移除指定文件中未使用的变量，并展示 diff
autoflake --remove-unused-variables {{路径/到/文件.py}}
# 移除多个文件中未使用的引入，并展示 diffs
autoflake --remove-all-unused-imports {{路径/到/文件1.py 路径/到/文件2.py ...}}
# 移除未被使用的变量，并覆盖更新
autoflake --remove-unused-variables --in-place {{路径/到/文件.py}}
# 递归地移除指定文件夹下层所有文件中未使用的变量，并覆盖更新
autoflake --remove-unused-variables --in-place --recursive {{路径/到/目录}}

# 将一组源文件编译为二进制文件
clang++ {{源/文件/的路径1.cpp 源/文件/的路径2.cpp ...}} {{[-o|--output]}} {{可执行/文件/的路径}}
# 打印所有错误和警告
clang++ {{源/文件/的路径.cpp}} -Wall {{[-o|--output]}} {{可执行文件}}
# 打印普通警告和调试信息, 并在不影响调试的情况下优化
clang++ {{源/文件/的路径.cpp}} -Wall {{[-g|--debug]}} -Og {{[-o|--output]}} {{可执行/文件/的路径}}
# 指定 C++ 语言标准
clang++ {{源/文件/的路径.cpp}} -std={{c++20}} {{[-o|--output]}} {{可执行/文件/的路径}}

# 运行 JavaScript 或 TypeScript 文件
deno run {{路径/到/文件.ts}}
# 启动 REPL（交互式 shell）
deno
# 运行文件并启用网络访问
deno run --allow-net {{路径/到/文件.ts}}
# 从 URL 运行文件
deno run {{https://deno.land/std/examples/welcome.ts}}

# 将一组源文件编译为二进制文件
g++ {{源/文件/的路径1.cpp 源/文件/的路径2.cpp ...}} {{[-o|--output]}} {{可执行/文件/的路径}}
# 打印所有错误和警告
g++ {{源/文件/的路径.cpp}} -Wall {{[-o|--output]}} {{output_executable}}
# 打印普通警告和调试信息, 并在不影响调试的情况下优化
g++ {{源/文件/的路径.cpp}} -Wall {{[-g|--debug]}} -Og {{[-o|--output]}} {{可执行/文件/的路径}}
# 指定 C++ 语言标准 (C++98/C++11/C++14/C++17)
g++ {{源/文件/的路径.cpp}} -std={{c++98|c++11|c++14|c++17}} {{[-o|--output]}} {{可执行/文件/的路径}}

# 将一组源文件编译为二进制文件
gcc {{源/文件/的路径1.cpp 源/文件/的路径2.cpp ...}} {{[-o|--output]}} {{可执行/文件/的路径}}
# 打印所有错误和警告
gcc {{源/文件/的路径.cpp}} -Wall {{[-o|--output]}} {{output_executable}}
# 打印普通警告和调试信息, 并在不影响调试的情况下优化
gcc {{源/文件/的路径.cpp}} -Wall {{[-g|--debug]}} -Og {{[-o|--output]}} {{可执行/文件/的路径}}
# 包含与源文件不在同一路径下的库
gcc {{源/文件/的路径.c}} {{[-o|--output]}} {{可执行/文件/的路径}} -I{{头/文件/的目录}} -L{{库/的目录}} -l{{库的名字}}

# 添加单个文件到索引
git add {{路径/到/文件}}
# 交互式挑选部分修改并暂存
git add {{[-p|--patch]}}
# 添加所有文件（包括已跟踪的和未跟踪的）
git add {{[-A|--all]}}
# 从当前文件夹开始递归地添加所有文件
git add .

# 初始化一个带有 Git annex 的仓库
git annex init
# 添加文件
git annex add {{路径/到/文件或目录}}
# 显示文件或目录的当前状态
git annex status {{路径/到/文件或目录}}
# 同步本地仓库与远程仓库
git annex {{远程仓库名}}

# 打印文件内容，并在每行前附加作者姓名和提交哈希值
git annotate {{路径/到/文件}}
# 打印文件内容，并在每行前附加作者邮箱和提交哈希值
git annotate {{[-e|--show-email]}} {{路径/到/文件}}
# 仅打印匹配正则表达式的行
git annotate -L :{{正则表达式}} {{路径/到/文件}}

# 显示补丁文件的应用详情
git apply {{[-v|--verbose]}} {{路径/到/文件}}
# 应用补丁并将修改添加到暂存区
git apply --index {{路径/到/文件}}
# 应用远程补丁文件
curl {{[-L|--location]}} {{https://example.com/file.patch}} | git apply
# 应用远程补丁文件
git apply --stat --apply {{路径/到/文件}}

# 显示文件的每一行，包含作者名字和提交哈希值
git blame {{路径/到/文件}}
# 显示文件的每一行，包含作者邮箱和提交哈希值
git blame {{[-e|--show-email]}} {{路径/到/文件}}
# 显示文件在指定提交时的每一行，包含作者名字和提交哈希值
git blame {{commit}} {{路径/到/文件}}
# 显示文件在指定提交之前的每一行，包含作者名字和提交哈希值
git blame {{commit}}~ {{路径/到/文件}}

# 列出所有分支（包括本地的和远程的；当前分支以 `*` 突出表示）
git branch {{[-a|--all]}}
# 列出哪些分支在其历史中包含指定的提交记录
git branch {{[-a|--all]}} --contains {{提交的哈希值}}
# 显示当前分支的名称
git branch --show-current
# 基于当前提交创建新分支
git branch {{分支名}}

# 在当前目录创建新的问题报告文件
git bugreport
# 在指定目录创建新的问题报告文件（如目录不存在则自动创建）
git bugreport {{[-o|--output-directory]}} {{path/to/directory}}
# 使用指定格式的时间戳后缀创建问题报告文件（ `strftime` 格式）
git bugreport {{[-s|--suffix]}} {{%m%d%y}}

# 将当前目录注册为工作区
git bulk --addcurrent {{工作区名称}}
# 注册一个工作区用于批量操作
git bulk --addworkspace {{工作区名称}} {{到仓库的绝对路径}}
# 在指定目录克隆仓库并注册为工作区
git bulk --addworkspace {{工作区名称}} {{仓库父目录的绝对路径}} --from {{远程仓库地址}}
# 从换行分隔的远程仓库列表克隆并注册为工作区
git bulk --addworkspace {{工作区名称}} {{/路径/到/根/目录}} --from {{/路径/到/文件}}

# 创建包含特定分支所有对象和引用的打包文件
git bundle create {{路径/到/文件.bundle}} {{分支名}}
# 创建包含所有分支的打包文件
git bundle create {{路径/到/文件.bundle}} --all
# 创建当前分支最近 5 次提交的打包文件
git bundle create {{路径/到/文件.bundle}} -5 {{HEAD}}
# 创建最近 7 天提交的打包文件
git bundle create {{路径/到/文件.bundle}} --since 7.days {{HEAD}}

# 获取 HEAD 提交的字节大小
git cat-file -s HEAD
# 获取指定 Git 对象的类型（blob、tree、commit、tag）
git cat-file -t {{8c442dc3}}
# 根据对象类型打印指定 Git 对象的内容
git cat-file -p {{HEAD~2}}

# 检查文件的所有属性状态
git check-attr {{[-a|--all]}} {{路径/到/文件}}
# 查看文件的某个特定属性值
git check-attr {{属性}} {{路径/到/文件}}
# 查看指定文件的所有属性值
git check-attr {{[-a|--all]}} {{路径/到/文件1 路径/到/文件2 ...}}
# 在一或多个文件上查看特定的属性值
git check-attr {{属性}} {{路径/到/文件1 路径/到/文件2 ...}}

# 检查文件或目录是否被忽略
git check-ignore {{路径/到/文件或目录}}
# 检查多个文件或目录是否被忽略
git check-ignore {{路径/到/文件或目录1 路径/到/文件或目录2 ...}}
# 从标准输入读取路径列表（每行一个路径）
git <{{路径/到/文件列表}} check-ignore --stdin
# 不检查索引（用于调试为何某些路径被跟踪而非忽略）
git check-ignore --no-index {{路径/到/文件或目录1 路径/到/文件或目录2 ...}}

# 检查指定引用名称的格式是否合法
git check-ref-format {{refs/head/refname}}
# 打印最近检出的分支名称
git check-ref-format --branch @{-1}
# 规范化引用名称格式
git check-ref-format --normalize {{refs/head/refname}}

# 创建并切换到新分支
git checkout -b {{分支名}}
# 基于指定引用（如分支、远程分支、标签等）创建并切换到新分支
git checkout -b {{分支名}} {{引用}}
# 切换到已有的本地分支
git checkout {{分支名}}
# 切换到上次检出的分支
git checkout -

# 恢复自上次提交以来删除的所有文件
git checkout-index {{[-a|--all]}}
# 恢复自上次提交以来删除或修改的所有文件（强制覆盖）
git checkout-index {{[-a|--all]}} {{[-f|--force]}}
# 恢复自上次提交以来修改的文件（忽略已删除的文件）
git checkout-index {{[-a|--all]}} {{[-f|--force]}} {{[-n|--no-create]}}
# 将最后一次提交的整个工作树导出到指定目录（注意结尾斜杠）
git checkout-index {{[-a|--all]}} {{[-f|--force]}} --prefix {{路径/到/导出目录}}/

# 显示已在上游分支有对应提交的提交（包含提交信息）
git cherry {{[-v|--verbose]}}
# 指定不同的上游分支和主题分支进行比较
git cherry {{上游分支}} {{主题分支}}
# 限定比较范围到某个基准点之后的提交
git cherry {{上游分支}} {{主题分支}} {{基准点}}

# 将单个提交应用到当前分支
git cherry-pick {{提交哈希}}
# 将连续多个提交应用到当前分支（也可参考 `git rebase --onto`）
git cherry-pick {{起始提交}}~..{{结束提交}}
# 将多个（非连续的）提交应用到当前分支
git cherry-pick {{提交1 提交2 ...}}
# 将提交变更应用到工作区但不自动创建提交
git cherry-pick {{[-n|--no-commit]}} {{提交哈希}}

# 删除未跟踪的文件
git clean
# 交互式删除未跟踪的文件
git clean {{[-i|--interactive]}}
# 显示将被删除的文件（模拟运行，不实际删除）
git clean {{[-n|--dry-run]}}
# 强制删除未跟踪的文件
git clean {{[-f|--force]}}

# 从 Git 仓库所有提交生成变更日志并保存到 `CHANGELOG.md`
git cliff >{{CHANGELOG.md}}
# 从最新标签之后的提交生成变更日志并输出到标准输出
git cliff {{[-l|--latest]}}
# 为当前标签对应的提交生成变更日志（需先使用 `git checkout` 检出到一个标签）
git cliff --current
# 为尚未打标签的提交生成变更日志
git cliff {{[-u|--unreleased]}}

# 克隆一个现有的代码仓库到指定目录
git clone {{远程代码库地址}} {{路径/到/目录}}
# 克隆一个现有的代码库和它的子模块
git clone --recursive {{远程代码库地址}}
# 仅克隆现有代码仓库的 `.git` 目录
git clone {{[-n|--no-checkout]}} {{远程_代码仓库_地址}}
# 克隆一个本地的代码库
git clone {{[-l|--local]}} {{路径/到/本地/代码库名}}

# 创建带有指定提交信息的提交对象
git commit-tree {{树对象哈希}} -m "{{提交信息}}"
# 从文件读取提交信息创建提交对象（使用 `-` 表示从标准输入读取）
git commit-tree {{树对象哈希}} -F {{路径/到/文件}}
# 创建 GPG 签名过的提交对象
git commit-tree {{树对象哈希}} -m "{{提交信息}}" {{[-S|--gpg-sign]}}
# 创建指定父提交的提交对象
git commit-tree {{树对象哈希}} -m "{{提交信息}}" -p {{父提交哈希}}

# 显示从昨天以来的所有提交
git commits-since {{yesterday}}
# 显示从上周以来的所有提交
git commits-since {{last week}}
# 显示从上个月以来的所有提交
git commits-since {{last month}}
# 显示从昨天下午 2 点以来的所有提交
git commits-since {{yesterday 2pm}}

# 统计所有对象并显示总磁盘使用量
git count-objects
# 统计所有对象并以易读格式显示总磁盘使用量（如 KB/MB）
git count-objects {{[-H|--human-readable]}}
# 显示详细统计信息（包括对象类型细分）
git count-objects {{[-v|--verbose]}}
# 以易读格式显示详细统计信息
git count-objects {{[-H|--human-readable]}} {{[-v|--verbose]}}

# 在当前 Git 仓库下复制文件，保留在同一目录
git cp {{原文件名}} {{新文件}}
# 复制文件到其他目录
git cp {{路径/到/源文件}} {{路径/到/新文件}}

# 创建本地分支
git create-branch {{分支名}}
# 创建本地分支并推送到 origin 远程
git create-branch {{[-r|--remote]}} {{分支名}}
# 创建本地分支并推送到 upstream 远程（常用于 fork 的工作流）
git create-branch {{[-r|--remote]}} upstream {{分支名}}

# 显示指定 Git 子命令的帮助信息
git help {{subcommand}}
# 在网络浏览器中显示指定 Git 子命令的帮助信息
git help {{[-w|--web]}} {{subcommand}}
# 列出所有可用的 Git 子命令
git help {{[-a|--all]}}
# 列出可用的指南
git help {{[-g|--guides]}}

# 将指定分支合并到当前分支
git merge {{分支名}}
# 编辑合并说明信息
git merge {{[-e|--edit]}} {{分支名}}
# 合并分支，创建合并提交
git merge --no-ff {{分支名}}
# 遇到冲突时中止合并
git merge --abort

# 从默认的远程仓库拉取代码并执行合并
git pull
# 从默认的远程仓库拉取代码并采用变基策略实现合并（将你的本地提交“移植”到远程获取的分支上）
git pull {{[-r|--rebase]}}
# 从给定的远程仓库和分支中拉取代码，并合并到本地对应分支
git pull {{远程仓库名}} {{分支名}}

# 将当前分支的本地更改推送到其默认的远程对应分支
git push
# 将指定本地分支的更改推送到其远程对应分支
git push {{远程仓库名}} {{本地分支名}}
# 将指定本地分支的更改推送到其远程对应分支，并将该远程分支设为该本地分支 push/pull 的默认目标分支
git push {{[-u|--set-upstream]}} {{远程仓库名}} {{本地分支名}}
# 将指定本地分支的更改推送到指定的远程分支
git push {{远程仓库名}} {{本地分支名}}:{{远程分支名}}

# 列出已经存在的远程仓库，包括它们的名字和 URL
git remote {{[-v|--verbose]}}
# 查看某个远程仓库的信息
git remote show {{远程仓库名字}}
# 添加远程仓库
git remote add {{远程仓库名字}} {{远程仓库url}}
# 更改远程仓库地址链接（使用 `--add` 选项不会移除现有的 URL）
git remote set-url {{远程仓库名字}} {{新url}}

# 重新命名你目前所在的分支
git rename-branch {{新的分支名称}}
# 重新命名一个特定的分支
git rename-branch {{旧的分支名称}} {{新的分支名称}}

# 从仓库索引和文件系统中删除文件
git rm {{路径/到/文件}}
# 删除目录
git rm -r {{路径/到/目录}}
# 从仓库索引中删除文件，但保留本地文件
git rm --cached {{路径/到/文件}}

# 显示修改过但尚未暂存（以备提交）的文件
git status
# 以简短形式输出
git status {{[-s|--short]}}
# 显示暂存区与工作目录的详细变更信息
git status {{[-vv|--verbose --verbose]}}
# 以简短形式输出，同时包含分支信息
git status {{[-sb|--short --branch]}}

# 切换到一个已有的分支
git switch {{分支名字}}
# 创建并切换到一个新分支
git switch {{[-c|--create]}} {{分支名字}}
# 创建并切换到基于某个提交的新分支
git switch {{[-c|--create]}} {{分支名字}} {{指定提交}}
# 切换到之前的分支
git switch -

# 编译 'package main' 文件（输出为不带扩展名的文件名）
go build {{路径/到/main.go}}
# 编译并指定输出文件名
go build -o {{路径/到/二进制文件}} {{路径/到/源文件.go}}
# 编译一个包
go build -o {{路径/到/二进制文件}} {{路径/到/包}}
# 编译 main 包为可执行文件，并开启数据竞态检测
go build -race -o {{路径/到/可执行文件}} {{路径/到/main/包}}

# 显示当前包的文档
go doc
# 显示包文档及导出符号
go doc {{encoding/json}}
# 同时显示符号的文档
go doc -all {{encoding/json}}
# 同时显示源代码
go doc -all -src {{encoding/json}}

# 显示所有环境变量
go env
# 显示指定的环境变量
go env {{GOPATH}}
# 设置某个环境变量为指定值
go env -w {{GOBIN}}={{路径/到/目录}}
# 重置某个环境变量的值
go env -u {{GOBIN}}

# 运行一个 Go 文件
go run {{路径/到/文件.go}}
# 运行一个 Go `main` 包
go run {{路径/到/包}}

# 格式化文件并在控制台输出结果
gofmt {{源代码.go}}
# 格式化文件并覆盖原文件
gofmt -w {{源代码.go}}
# 格式化文件和简化代码并覆盖原文件
gofmt -s -w {{源代码.go}}
# 打印所有（包括虚假的）错误
gofmt -e {{源代码.go}}

# 将一个 Dex 文件反编译到一个目录中
jadx {{路径/到/文件}}
# 将一个 Dex 文件反编译到一个特定目录中
jadx {{[-d|--output-dir]}} {{路径/到/目录}} {{路径/到/文件}}

# 初始化一个简单的 Java 类
jbang init {{路径/到/文件.java}}
# 初始化一个 Java 类（用于脚本编写）
jbang init {{[-t|--template]}}={{cli}} {{路径/到/文件.java}}
# 使用 `jshell` 在 REPL 编辑器中探索和使用脚本及其任何依赖项
jbang run {{[-i|--interactive]}}
# 设置一个临时项目以在 IDE 中编辑脚本
jbang edit --open={{codium|code|eclipse|idea|netbeans|gitpod}} {{路径/到/脚本.java}}

# 运行所有可用的测试
jest
# 从指定文件中运行测试套件
jest {{路径/到/文件1 路径/到/文件2 ...}}
# 从当前目录和子目录中路径匹配给定正则表达式的文件运行测试套件
jest {{正则表达式1 正则表达式2 ...}}
# 运行名称匹配给定正则表达式的测试
jest --testNamePattern {{正则表达式}}

# 打印 Java 进程的堆栈和锁信息
jhsdb jstack --pid {{进程id}}
# 在交互式调试模式下打开一个核心转储
jhsdb clhsdb --core {{路径/到/core_dump}} --exe {{路径/到/jdk/bin/java}}
# 启动远程调试服务器
jhsdb debugd --pid {{进程id}} --serverid {{可选的唯一标识}}
# 在交互式调试模式下连接到一个进程
jhsdb clhsdb --pid {{进程id}}

# 在非 GUI 模式下运行指定的测试计划
jmeter {{[-n|--nongui]}} {{[-t|--testfile]}} {{路径/到/文件.jmx}}
# 在非 GUI 模式下使用指定的日志文件运行测试计划
