scrapy edit {{爬虫名}}
# 运行爬虫（在项目目录下）
scrapy crawl {{爬虫名}}

# 在当前目录中创建一个新的 Python 项目
uv init
# 在具有指定名称的目录中创建一个新的 Python 项目
uv init {{项目名称}}
# 向项目中添加一个新的软件包
uv add {{软件包}}
# 从项目中移除一个软件包
uv remove {{软件包}}

# 构建工作区
xcodebuild -workspace {{工作区名.工作区}} -scheme {{主题名}} -configuration {{配置名}} clean build SYMROOT={{SYMROOT_路径}}
# 构建项目
xcodebuild -target {{目标名}} -configuration {{配置名}} clean build SYMROOT={{SYMROOT_路径}}
