binwalk {{[-e|--extract]}} {{[-M|--matryoshka]}} {{[-d|--depth]}} 2 {{二进制文件}}
# 解压一个二进制文件并指定文件签名
binwalk {{[-D|--dd]}} '{{png image:png}}' {{二进制文件}}

# 授予 direnv 当前目录中加载 `.envrc`
direnv allow {{.}}
# 撤销在当前目录加载 `.envrc` 的授权
direnv deny {{.}}
