direnv edit {{.}}
# 触发环境重载
direnv reload

# 使用自动重载运行 FastAPI 应用（用于开发）
fastapi run {{路径/文件.py}} --reload
# 在开发模式下运行应用
fastapi dev {{路径/文件.py}}
# 指定运行的主机和端口
fastapi run {{路径/文件.py}} --host {{主机地址}} --port {{端口}}
# 设置应用变量名（如果不是 `app`）或指定自定义应用目录
fastapi run {{路径/文件.py}} --app-dir {{路径/到/应用}} --app {{自定义_app_名称}}

# 将当前目录中的所有文件递归归档到 `.jar` 文件中
jar cf {{file.jar}} *
# 将 `.jar` / `.war` 文件解压缩到当前目录
jar -xvf {{file.jar}}
# 列出 `.jar` / `.war` 文件内容
jar tf {{path/to/file.jar}}
# 列出带有详细输出的 `.jar` / `.war` 文件内容
jar tvf {{path/to/file.jar}}

# 分析堆转储文件（来自 jmap），通过 HTTP 端口 7000 进行查看
jhat {{路径/堆转储文件}}
# 分析堆转储文件，为 HTTP 服务指定备用端口
jhat {{[-p|-port]}} {{端口}} {{路径/堆转储文件}}
