xed --create {{文件名}}
# 在 Xcode 中打开一个文件并跳转到第 75 行
xed --line 75 {{文件名}}

# 显示将要进行的更改的差异，但不实际更改（试运行）
yapf --diff {{路径/到/文件}}
# 就地格式化文件，并显示更改的差异
yapf --diff --in-place {{路径/到/文件}}
